message.content:
{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2126-05-10 21:44:00",
      "speaker": "Doctor",
      "text": "Hello, Mr. ___. I’m Dr. ___ and I’ll be part of your care team. You’re here because of trouble breathing, fever, and high heart rate. We’re going to help you get through this."
    },
    {
      "turn_number": 2,
      "time": "2126-05-10 21:45:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 3,
      "time": "2126-05-10 21:46:00",
      "speaker": "Doctor",
      "text": "You’re not able to speak right now because of your trach, but we’ll work with your sister later if needed. For now, I’ll explain what’s going on and what we’re doing."
    },
    {
      "turn_number": 4,
      "time": "2126-05-10 21:47:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 5,
      "time": "2126-05-10 21:48:00",
      "speaker": "Doctor",
      "text": "Your labs show a high white blood cell count, which means your body is fighting an infection. Your sodium is high, and your kidney function is a bit off. We think this is from dehydration and infection."
    },
    {
      "turn_number": 6,
      "time": "2126-05-10 21:49:00",
      "speaker": "Patient",
      "text": "Frown."
    },
    {
      "turn_number": 7,
      "time": "2126-05-10 21:50:00",
      "speaker": "Doctor",
      "text": "Don’t worry—we’re giving you fluids and antibiotics. You got meropenem and linezolid tonight to cover possible pneumonia and a resistant infection."
    },
    {
      "turn_number": 8,
      "time": "2126-05-10 21:51:00",
      "speaker": "Patient",
      "text": "Nod slowly."
    },
    {
      "turn_number": 9,
      "time": "2126-05-11 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your chest X-ray shows long-standing lung changes, but no new pneumonia yet. We’re watching closely."
    },
    {
      "turn_number": 10,
      "time": "2126-05-11 08:01:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 11,
      "time": "2126-05-11 08:02:00",
      "speaker": "Doctor",
      "text": "We placed a central line in your neck yesterday to give antibiotics safely. That will help us treat you better."
    },
    {
      "turn_number": 12,
      "time": "2126-05-11 08:03:00",
      "speaker": "Patient",
      "text": "Raise eyebrow."
    },
    {
      "turn_number": 13,
      "time": "2126-05-11 08:04:00",
      "speaker": "Doctor",
      "text": "It’s in your right internal jugular vein and goes into your heart. It’s secure and working well."
    },
    {
      "turn_number": 14,
      "time": "2126-05-11 08:05:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 15,
      "time": "2126-05-12 09:00:00",
      "speaker": "Doctor",
      "text": "We did a bronchoscopy yesterday to get samples from your lungs. It was safe, and we sent the fluid for testing."
    },
    {
      "turn_number": 16,
      "time": "2126-05-12 09:01:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 17,
      "time": "2126-05-12 09:02:00",
      "speaker": "Doctor",
      "text": "The results came back. You have Klebsiella and two types of Pseudomonas in your lungs. One Pseudomonas is resistant to some antibiotics, but we’re using meropenem and will switch to cefepime."
    },
    {
      "turn_number": 18,
      "time": "2126-05-12 09:03:00",
      "speaker": "Patient",
      "text": "Frown."
    },
    {
      "turn_number": 19,
      "time": "2126-05-12 09:04:00",
      "speaker": "Doctor",
      "text": "We’re on top of it. Cefepime works well against this bug. You’ll get it through your IV for 7 days."
    },
    {
      "turn_number": 20,
      "time": "2126-05-12 09:05:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 21,
      "time": "2126-05-12 09:06:00",
      "speaker": "Doctor",
      "text": "We also found Enterococcus faecium in your urine. It’s resistant to vancomycin, but linezolid covers it. You’re finishing that course now."
    },
    {
      "turn_number": 22,
      "time": "2126-05-12 09:07:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 23,
      "time": "2126-05-13 08:00:00",
      "speaker": "Doctor",
      "text": "Your CT scan shows thickened airway walls, likely from infection or aspiration. No focal pneumonia, so we’re on the right track with antibiotics."
    },
    {
      "turn_number": 24,
      "time": "2126-05-13 08:01:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 25,
      "time": "2126-05-13 08:02:00",
      "speaker": "Doctor",
      "text": "We also saw small pleural effusions—fluid around the lungs. They’re not large, so we’re not draining them. They may be from infection or heart strain."
    },
    {
      "turn_number": 26,
      "time": "2126-05-13 08:03:00",
      "speaker": "Patient",
      "text": "Raise eyebrow."
    },
    {
      "turn_number": 27,
      "time": "2126-05-13 08:04:00",
      "speaker": "Doctor",
      "text": "We’ll watch them. Your heart looks okay, but your lung disease makes it harder to tell."
    },
    {
      "turn_number": 28,
      "time": "2126-05-13 08:05:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 29,
      "time": "2126-05-14 08:00:00",
      "speaker": "Doctor",
      "text": "You’re doing better. Your fever is gone, and your breathing is easier. Your blood pressure is still on the lower side, but that’s your baseline."
    },
    {
      "turn_number": 30,
      "time": "2126-05-14 08:01:00",
      "speaker": "Patient",
      "text": "Smile slightly."
    },
    {
      "turn_number": 31,
      "time": "2126-05-14 08:02:00",
      "speaker": "Doctor",
      "text": "We’re keeping you on cefepime. It’s important to finish the full course to fully treat the Pseudomonas."
    },
    {
      "turn_number": 32,
      "time": "2126-05-14 08:03:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 33,
      "time": "2126-05-14 08:04:00",
      "speaker": "Doctor",
      "text": "We started a scopolamine patch to help reduce your lung secretions. It’s changed every 3 days."
    },
    {
      "turn_number": 34,
      "time": "2126-05-14 08:05:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 35,
      "time": "2126-05-15 08:00:00",
      "speaker": "Doctor",
      "text": "Your white count is coming down—great sign the antibiotics are working. Your kidney function is also improving."
    },
    {
      "turn_number": 36,
      "time": "2126-05-15 08:01:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 37,
      "time": "2126-05-15 08:02:00",
      "speaker": "Doctor",
      "text": "We’re still giving your home meds—Keppra for seizures, your HIV meds, and vancomycin for C. diff prevention."
    },
    {
      "turn_number": 38,
      "time": "2126-05-15 08:03:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 39,
      "time": "2126-05-15 08:04:00",
      "speaker": "Doctor",
      "text": "We held your citalopram while on linezolid because they can interact. We’ll restart it soon."
    },
    {
      "turn_number": 40,
      "time": "2126-05-15 08:05:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 41,
      "time": "2126-05-16 08:00:00",
      "speaker": "Doctor",
      "text": "We placed a PICC line in your left arm yesterday for long-term antibiotics. The X-ray confirms it’s in the right spot."
    },
    {
      "turn_number": 42,
      "time": "2126-05-16 08:01:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 43,
      "time": "2126-05-16 08:02:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’re planning for discharge in a few days once antibiotics are complete."
    },
    {
      "turn_number": 44,
      "time": "2126-05-16 08:03:00",
      "speaker": "Patient",
      "text": "Smile."
    },
    {
      "turn_number": 45,
      "time": "2126-05-17 08:00:00",
      "speaker": "Doctor",
      "text": "You’re on day 5 of cefepime. Two more doses to go. Your breathing is stable, and you’re off pressors."
    },
    {
      "turn_number": 46,
      "time": "2126-05-17 08:01:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 47,
      "time": "2126-05-17 08:02:00",
      "speaker": "Doctor",
      "text": "We added a lidocaine patch for your right thigh pain. How’s that helping?"
    },
    {
      "turn_number": 48,
      "time": "2126-05-17 08:03:00",
      "speaker": "Patient",
      "text": "Thumbs up."
    },
    {
      "turn_number": 49,
      "time": "2126-05-18 08:00:00",
      "speaker": "Doctor",
      "text": "Great. We did a swallow study today. No aspiration seen—good news. You may be able to eat by mouth again at your facility."
    },
    {
      "turn_number": 50,
      "time": "2126-05-18 08:01:00",
      "speaker": "Patient",
      "text": "Smile widely."
    },
    {
      "turn_number": 51,
      "time": "2126-05-18 08:02:00",
      "speaker": "Doctor",
      "text": "We’ll continue tube feeds for now, but this is a positive step."
    },
    {
      "turn_number": 52,
      "time": "2126-05-18 08:03:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 53,
      "time": "2126-05-19 08:00:00",
      "speaker": "Doctor",
      "text": "Almost done. One more dose of cefepime tomorrow. Your labs are nearly normal."
    },
    {
      "turn_number": 54,
      "time": "2126-05-19 08:01:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 55,
      "time": "2126-05-19 08:02:00",
      "speaker": "Doctor",
      "text": "We’ll restart your citalopram tomorrow. And keep taking oral vancomycin for two more weeks after antibiotics end."
    },
    {
      "turn_number": 56,
      "time": "2126-05-19 08:03:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 57,
      "time": "2126-05-20 09:00:00",
      "speaker": "Doctor",
      "text": "Good news—you’re being discharged today to your extended care facility."
    },
    {
      "turn_number": 58,
      "time": "2126-05-20 09:01:00",
      "speaker": "Patient",
      "text": "Smile."
    },
    {
      "turn_number": 59,
      "time": "2126-05-20 09:02:00",
      "speaker": "Doctor",
      "text": "You’ll finish the cefepime today. Keep the scopolamine patch and lidocaine patch as prescribed."
    },
    {
      "turn_number": 60,
      "time": "2126-05-20 09:03:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 61,
      "time": "2126-05-20 09:04:00",
      "speaker": "Doctor",
      "text": "Restart citalopram today. Continue oral vancomycin until two weeks after cefepime ends."
    },
    {
      "turn_number": 62,
      "time": "2126-05-20 09:05:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 63,
      "time": "2126-05-20 09:06:00",
      "speaker": "Doctor",
      "text": "Follow up with pulmonology for your lung condition. Your sister has all the details."
    },
    {
      "turn_number": 64,
      "time": "2126-05-20 09:07:00",
      "speaker": "Patient",
      "text": "Nod."
    },
    {
      "turn_number": 65,
      "time": "2126-05-20 09:08:00",
      "speaker": "Doctor",
      "text": "You did great. We’re proud of your progress. Take care."
    },
    {
      "turn_number": 66,
      "time": "2126-05-20 09:09:00",
      "speaker": "Patient",
      "text": "Nod, then weak thumbs up."
    }
  ],
  "summary": {
    "admission_start": "2126-05-10 21:44:00",
    "admission_end": "2126-05-20 17:52:00",
    "summary_paragraph": "A man with HIV/AIDS, chronic respiratory failure, tracheostomy, and functional quadriplegia was admitted with septic shock and respiratory distress. He was found to have ventilator-associated pneumonia caused by Klebsiella pneumoniae and multidrug-resistant Pseudomonas aeruginosa, treated with a 7-day course of meropenem followed by cefepime. A vancomycin-resistant Enterococcus faecium urinary infection was covered by linezolid. His sepsis resolved, and he improved clinically with stable vitals and reduced secretions. He was discharged to extended care with plans to complete cefepime, continue oral vancomycin for C. diff prophylaxis, restart citalopram, and follow up with pulmonology.",
    "problems": [
      "Human immunodeficiency virus [HIV] disease",
      "Severe sepsis with septic shock",
      "Ventilator associated pneumonia",
      "Pneumonia due to Klebsiella pneumoniae",
      "Pneumonia due to Pseudomonas",
      "Urinary tract infection, site not specified",
      "Recurrent C. difficile",
      "Chronic respiratory failure with hypoxia",
      "Functional quadriplegia",
      "Tracheostomy status",
      "Epilepsy, unspecified, not intractable, without status epilepticus",
      "Major depressive disorder, single episode, unspecified",
      "Anxiety disorder, unspecified",
      "Dependence on supplemental oxygen"
    ]
  }
}
